const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:transparent;overflow:hidden;touch-action:none;';

const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
canvas.width = c.offsetWidth || 400; canvas.height = c.offsetHeight || 500;
c.appendChild(canvas);

let particles = [];

c.addEventListener('pointermove', e => {
  const rect = c.getBoundingClientRect();
  // ધુમાડાના કણો ઉત્પન્ન કરવા
  for(let i=0; i<2; i++){
    particles.push({
      x: e.clientX - rect.left, 
      y: e.clientY - rect.top,
      size: Math.random() * 10 + 5, 
      life: 1,
      vx: (Math.random() - 0.5) * 2, 
      vy: -(Math.random() * 2 + 1) // ધુમાડો હંમેશા ઉપર જાય છે
    });
  }
});

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < particles.length; i++) {
    let p = particles[i];
    ctx.fillStyle = `rgba(180, 180, 200, ${p.life * 0.5})`;
    ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI*2); ctx.fill();

    p.x += p.vx; p.y += p.vy; 
    p.size += 0.3; // કણો ધીમે ધીમે મોટા થાય
    p.life -= 0.02; // કણો ધીમે ધીમે ગાયબ થાય

    if(p.life <= 0) { particles.splice(i, 1); i--; }
  }
  requestAnimationFrame(draw);
}
draw();
